-- Column level governance actions on ALTER DYNAMIC TABLE
-- https://docs.snowflake.com/en/sql-reference/sql/alter-dynamic-table

ALTER DYNAMIC TABLE t ALTER COLUMN c1 SET MASKING POLICY mp;

ALTER DYNAMIC TABLE t MODIFY COLUMN c1 SET MASKING POLICY my_db.my_schema.mp USING (c1, c2) FORCE;

ALTER DYNAMIC TABLE t ALTER COLUMN c1 UNSET MASKING POLICY;

ALTER DYNAMIC TABLE t MODIFY c1 SET MASKING POLICY mp;

ALTER DYNAMIC TABLE t ALTER COLUMN c1 SET PROJECTION POLICY pp;

ALTER DYNAMIC TABLE t MODIFY COLUMN c1 UNSET PROJECTION POLICY;

ALTER DYNAMIC TABLE t MODIFY COLUMN c1 SET TAG tg = 'v';

ALTER DYNAMIC TABLE t ALTER COLUMN c1 SET TAG tag1 = 'v1', tag2 = 'v2';

ALTER DYNAMIC TABLE t MODIFY COLUMN c1 UNSET TAG tg;

ALTER DYNAMIC TABLE IF EXISTS t ALTER COLUMN c1 UNSET TAG tag1, tag2;
